import com.unitepaintball.app.GiftBookingPricing;
public final class GiftBookingPricingTest {private static void eq(int a,int b){if(a!=b)throw new AssertionError(a+" != "+b);}public static void main(String[] args){eq(GiftBookingPricing.discount("percent",25,false,"","base",4,true,35,4,10,180),45);eq(GiftBookingPricing.discount("amount",200,false,"","base",4,true,35,4,10,180),180);eq(GiftBookingPricing.discount("free_players",2,true,"base","base",4,true,35,4,10,180),90);eq(GiftBookingPricing.discount("three_plus_one",0,true,"","base",4,true,35,4,10,180),45);eq(GiftBookingPricing.discount("custom",0,false,"","base",4,true,35,4,10,180),0);for(int n=0;n<3;n++){boolean failed=false;try{GiftBookingPricing.discount("three_plus_one",0,false,n==2?"group":"","base",n==0?3:4,n!=1,35,0,10,180);}catch(IllegalArgumentException e){failed=true;}if(!failed)throw new AssertionError();}System.out.println("8 contrôles prix bon cadeau OK");}}
